
package org.strathclyde.service;

import java.time.LocalDateTime;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;

public class EventLog {

    // Stores all events generated by the spaceport.
    private final List<String> events = new ArrayList<>();
    private final List<Consumer<String>> listeners = new CopyOnWriteArrayList<>();

    // Records a new event.
    public void recordEvent(
            String eventType,
            String transportId,
            String resourceId,
            String description) {

        // Get the current date and time.
        LocalDateTime timestamp = LocalDateTime.now();

        // Create the event entry.
        String event = timestamp
                + " | " + eventType
                + " | Transport: " + transportId
                + " | Resource: " + resourceId
                + " | " + description;

        // Add the event to the shared list.
        // Synchronized protects the shared event list
        // when multiple threads try to add events.
        synchronized (this) {
            events.add(event);
        }

        // Display the event in the console.
        System.out.println("EVENT LOG: " + event);

        // Notify after the lock is released, so a slow listened can't block other operations
        for (Consumer<String> listener : listeners) {
            listener.accept(event);
        }
    }

    // Returns a safe copy of all recorded events.
    public synchronized List<String> getEvents() {
        return Collections.unmodifiableList(
                new ArrayList<>(events)
        );
    }

    public void addListener(Consumer<String> listener){
        listeners.add(listener);
    }
}
